function buildIsuzuDetail(subject: string, language: string): string {
  const suffix = isuzuDetailTemplates[language]?.suffix || isuzuDetailTemplates.en.suffix;
  return language === 'zh' ? `${subject}，${suffix}` : `${subject} ${suffix}`;
}

export function getTranslatedIsuzuSparePartDetails(name: string, language: string = 'en'): string {
  const detailKind = isuzuPartDetailKinds[name];
  if (detailKind) {
    const subject = isuzuDetailSubjects[detailKind][language] || isuzuDetailSubjects[detailKind].en;
    return buildIsuzuDetail(subject, language);
  }

  return (isuzuPartDetailsTranslations.default as Record<string, string>)[language]
    || isuzuPartDetailsTranslations.default.en;
}
